from src.nodes.base import BaseNode
from src.runtime.assets.realization import get_asset_dependency_resolver
import json

class Hou_Mcp_Asset_Dependencies(BaseNode):
    name = "hou_mcp_asset_dependencies"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("asset_json", "string", widget_type="text")
        self.add_output("dependency_result_json", "string")
        self.add_output("textures_json",          "string")
        self.add_output("materials_json",         "string")
        self.add_output("references_json",        "string")
        self.add_output("missing_count",          "int")
        self.add_output("resolve_ok",             "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        asset_json = inputs.get("asset_json", "") or ""

        if not asset_json.strip():
            self.log_error("No asset_json provided.")
            return {"dependency_result_json": "{}", "textures_json": "[]", "materials_json": "[]", "references_json": "[]", "missing_count": 0, "resolve_ok": False, "exec_out": True}

        try:
            asset = json.loads(asset_json)
        except Exception as exc:
            self.log_error(f"Failed to parse asset_json: {exc}")
            return {"dependency_result_json": "{}", "textures_json": "[]", "materials_json": "[]", "references_json": "[]", "missing_count": 0, "resolve_ok": False, "exec_out": True}

        try:
            result = get_asset_dependency_resolver().resolve(asset)
            self.log_info(f"Dependencies resolved: {len(result.textures)} textures, {len(result.materials)} materials, {len(result.missing_deps)} missing")
            return {
                "dependency_result_json": json.dumps(result.to_dict(), sort_keys=True, default=str),
                "textures_json":          json.dumps(result.textures, default=str),
                "materials_json":         json.dumps(result.materials, default=str),
                "references_json":        json.dumps(result.references, default=str),
                "missing_count":          len(result.missing_deps),
                "resolve_ok":             result.ok,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Dependency resolution failed: {exc}")
            return {"dependency_result_json": "{}", "textures_json": "[]", "materials_json": "[]", "references_json": "[]", "missing_count": 0, "resolve_ok": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Dependencies
